{
  "findings": [
    {
      "check_id": "CKV2_AWS_11",
      "title": "VPC flow logging is not enabled",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The VPC has no associated flow log, limiting visibility into accepted and rejected network traffic during monitoring and incident investigations."
    },
    {
      "check_id": "CKV2_AWS_12",
      "title": "Default VPC security group does not explicitly restrict traffic",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The VPC's default security group is unmanaged, so its default rules can permit traffic between resources assigned to that group. Explicitly managing it with no ingress or egress rules prevents unintended use."
    }
  ],
  "patched_code": "data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_vpc" "changeme_aws_vpc_simple" {
  cidr_block = "10.1.0.0/16"
}

resource "aws_default_security_group" "changeme_aws_vpc_simple" {
  vpc_id = aws_vpc.changeme_aws_vpc_simple.id
}

resource "aws_cloudwatch_log_group" "changeme_aws_vpc_simple_flow_logs" {
  name              = "/aws/vpc/flow-logs/${aws_vpc.changeme_aws_vpc_simple.id}"
  retention_in_days = 365
}

resource "aws_iam_role" "changeme_aws_vpc_simple_flow_logs" {
  name_prefix = "vpc-flow-logs-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:ec2:*:${data.aws_caller_identity.current.account_id}:vpc-flow-log/*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "changeme_aws_vpc_simple_flow_logs" {
  role = aws_iam_role.changeme_aws_vpc_simple_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.changeme_aws_vpc_simple_flow_logs.arn}:*"
      },
      {
        Effect   = "Allow"
        Action   = "logs:DescribeLogGroups"
        Resource = aws_cloudwatch_log_group.changeme_aws_vpc_simple_flow_logs.arn
      }
    ]
  })
}

resource "aws_flow_log" "changeme_aws_vpc_simple" {
  vpc_id               = aws_vpc.changeme_aws_vpc_simple.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.changeme_aws_vpc_simple_flow_logs.arn
  iam_role_arn         = aws_iam_role.changeme_aws_vpc_simple_flow_logs.arn
}
",
  "fix_summary": "Added CloudWatch VPC flow logging for all traffic with a retained log group and scoped delivery role. Explicitly managed the VPC's default security group with no ingress or egress rules."
}
